{
  "declined": "none",
  "items": [
    {
      "i": 0,
      "revised": "My perfect weekend is very simple.",
      "why": "",
      "zh": "我理想的週末非常簡單。"
    },
    {
      "i": 1,
      "revised": "On Saturday I went to the park with my grandmother.",
      "why": "修正動詞時態錯誤，把 \"goed\" 改為正確的過去式 \"went\"。",
      "zh": "星期六我和奶奶去了公園。"
    },
    {
      "i": 2,
      "revised": "She likes the flowers there very much.",
      "why": "修正語序和動詞形式，將 \"She very like\" 改為正確自然的 \"She likes ... very much\"。",
      "zh": "她非常喜歡那裡的花。"
    },
    {
      "i": 3,
      "revised": "We ate an apple and talked about my school.",
      "why": "修正動詞時態和冠詞錯誤，把 \"eat\" 和 \"talk\" 改為過去式 \"ate\"、\"talked\"，並把 \"a apple\" 改為正確的 \"an apple\"。",
      "zh": "我們吃了一顆蘋果，並談論我的學校。"
    },
    {
      "i": 4,
      "revised": "On Sunday I don't go out.",
      "why": "",
      "zh": "星期天我不外出。"
    },
    {
      "i": 5,
      "revised": "I stay at home and read comic books.",
      "why": "",
      "zh": "我待在家裡看漫畫書。"
    }
  ]
}
